    /** Test driver (do not modify): builds the list, calls reverseKGroup, checks the nodes, returns the values. */
    public List<Integer> solve(int[] values, int k) {
        ListNode[] nodes = new ListNode[values.length];
        Map<ListNode, Integer> original = new IdentityHashMap<>();
        for (int i = 0; i < values.length; i++) {
            nodes[i] = new ListNode(values[i]);
            original.put(nodes[i], values[i]);
        }
        for (int i = 0; i + 1 < nodes.length; i++) nodes[i].next = nodes[i + 1];
        List<Integer> out = new ArrayList<>();
        for (ListNode node = reverseKGroup(nodes.length > 0 ? nodes[0] : null, k); node != null; node = node.next) {
            if (out.size() > nodes.length) throw new IllegalStateException("the returned list has a cycle");
            Integer val = original.get(node);
            if (val == null || val != node.val) {
                throw new IllegalStateException("relink the original nodes; do not create nodes or change their values");
            }
            out.add(node.val);
        }
        return out;
    }
}
